"""Original PDFium crops, main and matched SI; private review output only."""
from pathlib import Path
import json,hashlib
import pypdfium2 as pdfium
from PIL import Image
B=Path(__file__).resolve().parents[1];O=B/'reader-assets';O.mkdir(exist_ok=True)
read=lambda p:json.loads(p.read_text(encoding='utf8'));sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
info=read(B/'source-manifest.json');sources={d['role_candidate']:d for d in info['documents'] if d['role_candidate'] in ['main','si']};docs={k:pdfium.PdfDocument(v['path']) for k,v in sources.items()}
specs=[('figure-1', 'figure', 'main', 3, (92, 68, 517, 748), 'Figure 1 · Individual PbSe nanocrystal and polycrystalline spherical assemblies'), ('figure-2', 'figure', 'main', 3, (550, 68, 974, 468), 'Figure 2 · Wire-like assemblies, junction and selected-area electron diffraction'), ('figure-3', 'figure', 'main', 4, (92, 67, 517, 1020), 'Figure 3 · Bent assembly and high-resolution lattice fringes'), ('figure-4', 'figure', 'main', 4, (550, 67, 974, 486), 'Figure 4 · Absorption of spherical assemblies at three growth times'), ('figure-5', 'figure', 'main', 5, (92, 65, 974, 715), 'Figure 5 · Device architecture, actual contacted wire and current–voltage measurements'), ('synthesis-method', 'source_note', 'main', 2, (92, 888, 517, 1287), 'Source method · Stocks, rapid injection and temperature branches'), ('workup-method', 'source_note', 'main', 2, (550, 65, 974, 194), 'Source method · Aliquot quenching and purification'), ('characterization-method', 'source_note', 'main', 2, (550, 195, 974, 443), 'Source methods · Microscopy, electron diffraction and absorption'), ('device-method', 'source_note', 'main', 2, (550, 447, 974, 905), 'Source method · Single-wire circuit fabrication and measurement'), ('dipole-model', 'equation', 'main', 5, (92, 953, 517, 1288), 'Source inline models · Dipole moment and dipole–dipole energy'), ('transport-model', 'equation', 'main', 6, (92, 65, 517, 770), 'Source inline models · Internal field, capacitance, transfer energy and barriers'), ('assembly-model', 'source_note', 'main', 5, (550, 722, 974, 1099), 'Source interpretation · Entropy, assembly kinetics and TOPO impurity effects'), ('summary-conflict', 'source_note', 'main', 6, (92, 776, 517, 1285), 'Source summary · Printed stock-ratio and electric-field terminology conflicts')]
manifest={'schema_version':'1.0','source_id':'sashchiuk2004','doi':'10.1021/nl0345116','review_status':'private_proposal_pending_independent_audit','page_inspection':{'main':list(range(1,8)),'si':[],'text_read':True,'visual_reviewed':True},'sources':[{'role':k,'source':v['path'],'sha256':v['sha256'],'page_count':v['page_count']} for k,v in sources.items()],'supporting_information':{'status':'not_located','evidence':'No SI declaration observed in the supplied seven-page main article; no matched local SI available in the current source bundle.'},'assets':[]};cache={}
for key,kind,role,n,bbox,label in specs:
 src=Path(sources[role]['path']);assert sha(src)==sources[role]['sha256']
 if (role,n) not in cache:
  page=docs[role][n-1];cache[role,n]=(page.render(scale=300/72).to_pil().copy(),page.get_size())
 full,psize=cache[role,n];base=Image.open(B/(f'main-{n}.png' if role=='main' else f'si-{n}.png'));norm=[bbox[0]/base.width,bbox[1]/base.height,bbox[2]/base.width,bbox[3]/base.height];px=tuple(round(v*(full.width if i%2==0 else full.height)) for i,v in enumerate(norm));crop=full.crop(px);output=O/(key+'.png');crop.save(output)
 manifest['assets'].append({'id':key,'source_asset_type':kind,'label':label,'relative_asset':output.name,'public_asset':f'assets/figures/sashchiuk2004/{output.name}','sha256':sha(output),'source_role':role,'source_pdf_page':n,'source_filename':src.name,'source_sha256':sources[role]['sha256'],'crop_bbox_reference_pixels_125dpi':bbox,'reference_render_size':list(base.size),'crop_bbox_pdf_points_top_left':[v*psize[i%2] for i,v in enumerate(norm)],'crop_normalized':norm,'render_dpi':300,'pixel_dimensions':list(crop.size),'transformation':'Original PDF rendered with PDFium at 300 dpi and rectangularly cropped only. Source curves, microscopy, glyphs and author image processing preserved. No redraw or reconstruction.','text_reviewed':True,'visual_reviewed':False,'reviewed':False,'reader_render_verified':False})
(O/'crop-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Prepared',len(manifest['assets']),'original source crops')
